Understood. We'll incorporate the expanded programming language equivalence into our checks. We'll count missing qualifications per applicant using the job requirements and the programming equivalence (C++, C#, Fortran, Python, Perl).
```python
import pandas as pd

df = pd.read_excel('./workdir/Applicants.xlsx')

allowed_fields = {'Biology','Biochemistry','Biotechnology'}
allowed_degrees = {'Masters','PhD'}
allowed_langs = {'C++','C#','Fortran','Python','Perl'}  # expanded per Validation_Expert note

def missing_count(row):
    missing = 0
    if (row['Degree Level'] not in allowed_degrees) or (row['Degree Field'] not in allowed_fields):
        missing += 1
    if row['Experience (Years)'] < 3:
        missing += 1
    if str(row['Lab Trained (Y/N)']).strip().upper() != 'Y':
        missing += 1
    if row['Publications'] < 3:
        missing += 1
    if str(row['Citizen (Y/N)']).strip().upper() != 'Y':
        missing += 1
    if str(row['Programming Lang']).strip() not in allowed_langs:
        missing += 1
    # second language required
    if pd.isna(row['Second Language']) or str(row['Second Language']).strip() == '':
        missing += 1
    return missing

counts = df.apply(missing_count, axis=1)
result = (counts == 1).sum()
print(f"Number of applicants missing exactly one qualification: {result}")
```
